const input = Array.isArray($json) ? $json : [$json];
const rows = input.map((call) => {
  const text = `${call.voicemailText ?? ''} ${call.callTime ?? ''}`.toLowerCase();
  const afterHours = /T(17|18|19|20|21|22|23):/.test(call.callTime ?? '');
  const emergency = ['stopped cooling', 'not cooling', 'kids rooms', 'hot', 'no cool'].some((term) => text.includes(term));
  const priorityScore = (afterHours ? 1 : 0) + (emergency ? 3 : 0) + (call.repeatCaller ? 1 : 0);
  return { ...call, priorityScore, queue: priorityScore >= 3 ? 'call-now' : 'next-business-block' };
});
return rows.sort((a, b) => b.priorityScore - a.priorityScore).map((row) => ({ json: row }));
